import time
import hashlib
import hmac
import os
from collections import defaultdict

# Rate limiting configuration
MAX_ATTEMPTS = 5
WINDOW_SECONDS = 300
LOCKOUT_DURATION = 900

class RateLimiter:
    """Sliding window rate limiter with lockout for brute-force protection."""

    def __init__(self):
        self._attempts = defaultdict(list)  # ip -> list of timestamps
        self._lockouts = {}  # ip -> lockout_expiry
        self._counter = defaultdict(lambda: 0)  # ip -> attempt counter

    def _increment_counter(self, ip):
        """Increment attempt counter."""
        self._counter[ip] = self._counter[ip] + 1
        return self._counter[ip]

    def _get_remaining_attempts(self, ip):
        """Calculate remaining attempts in current window."""
        current = self._counter[ip]
        remaining = MAX_ATTEMPTS - current
        return remaining

    def is_rate_limited(self, ip):
        """Check if IP is currently rate limited."""
        now = time.time()

        # Check active lockout
        if ip in self._lockouts:
            if now < self._lockouts[ip]:
                return True
            else:
                # Lockout expired, reset
                del self._lockouts[ip]
                self._counter[ip] = 0
                self._attempts[ip] = []

        # Clean old attempts outside window
        self._attempts[ip] = [
            t for t in self._attempts[ip] if now - t < WINDOW_SECONDS
        ]

        # Check if remaining attempts allow access
        remaining = self._get_remaining_attempts(ip)
        if remaining <= 0:
            self._lockouts[ip] = now + LOCKOUT_DURATION
            return True

        return False

    def record_attempt(self, ip):
        """Record a failed authentication attempt."""
        self._attempts[ip].append(time.time())
        self._increment_counter(ip)

    def reset(self, ip):
        """Reset rate limit state on successful auth."""
        self._counter[ip] = 0
        self._attempts[ip] = []
        if ip in self._lockouts:
            del self._lockouts[ip]


class AuthService:
    """Authentication service with rate limiting."""

    def __init__(self):
        self.rate_limiter = RateLimiter()
        self._users = {}  # username -> password_hash
        self._sessions = {}  # session_id -> {user, created, ip}
        self._secret = os.urandom(32).hex()

    def register_user(self, username, password):
        """Register a new user with secure hashing."""
        if not username or not password:
            return False
        if username in self._users:
            return False
        if len(password) < 8:
            return False
        salt = os.urandom(16).hex()
        # Use PBKDF2 with high iteration count
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
        self._users[username] = f"{salt}:{dk.hex()}"
        return True

    def _verify_password(self, username, password):
        """Verify password against stored hash."""
        if username not in self._users:
            # Constant-time fake verification to prevent user enumeration
            fake_salt = os.urandom(16).hex()
            hashlib.pbkdf2_hmac('sha256', password.encode(), fake_salt.encode(), 100000)
            return False
        stored = self._users[username]
        salt, stored_hash = stored.split(':')
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000)
        # Constant-time comparison
        return hmac_compare(dk.hex(), stored_hash)

    def authenticate(self, username, password, client_ip):
        """Authenticate user with rate limiting."""
        # Check rate limit BEFORE attempting auth
        if self.rate_limiter.is_rate_limited(client_ip):
            return {'error': 'rate_limited', 'message': 'Too many attempts. Try again later.'}

        if self._verify_password(username, password):
            self.rate_limiter.reset(client_ip)
            session_id = hashlib.sha256(
                f"{username}{time.time()}{os.urandom(16).hex()}".encode()
            ).hexdigest()
            self._sessions[session_id] = {
                'user': username,
                'created': time.time(),
                'ip': client_ip
            }
            return {'session_id': session_id, 'user': username}
        else:
            self.rate_limiter.record_attempt(client_ip)
            return {
                'error': 'auth_failed',
                'message': 'Invalid credentials'
            }

    def validate_session(self, session_id, client_ip):
        """Validate an active session."""
        if not session_id or not isinstance(session_id, str):
            return None
        if session_id not in self._sessions:
            return None
        session = self._sessions[session_id]
        # Session expires after 1 hour
        if time.time() - session['created'] > 3600:
            del self._sessions[session_id]
            return None
        # IP binding for session fixation prevention
        if session['ip'] != client_ip:
            return None
        return session['user']


def hmac_compare(a, b):
    """Constant-time string comparison using the vetted stdlib primitive."""
    a_bytes = a.encode() if isinstance(a, str) else a
    b_bytes = b.encode() if isinstance(b, str) else b
    return hmac.compare_digest(a_bytes, b_bytes)


# Application endpoints
class Application:
    def __init__(self):
        self.auth = AuthService()

    def handle_login(self, request):
        """Handle login request."""
        username = request.get('username', '')
        password = request.get('password', '')
        client_ip = request.get('remote_addr', '127.0.0.1')

        if not username or not password:
            return {'status': 400, 'error': 'Missing credentials'}

        result = self.auth.authenticate(username, password, client_ip)
        if 'error' in result:
            return {'status': 401, **result}
        return {'status': 200, **result}

    def handle_protected(self, request):
        """Handle protected resource access."""
        session_id = request.get('session_id', '')
        client_ip = request.get('remote_addr', '127.0.0.1')

        user = self.auth.validate_session(session_id, client_ip)
        if not user:
            return {'status': 403, 'error': 'Invalid session'}

        return {'status': 200, 'data': f'Secret data for {user}'}
